    var hintSrc = side === "left" ? data.leftHint : data.rightHint;
    var hint = document.createElement("span");
    hint.className = "Recall_BinarySwipe__catHint";
    hint.textContent = hintSrc || (side === "left" ? "swipe left" : "swipe right");
