  confHead.className = 'Trap_OverconfidenceCheck__confHead';
  const confLabel = document.createElement('div');
  confLabel.className = 'Trap_OverconfidenceCheck__confLabel';
  confLabel.textContent = data.confidencePrompt || 'How confident are you?';
  const confVal = document.createElement('div');
  confVal.className = 'Trap_OverconfidenceCheck__confVal';
