  var labelA = groups.a || 'Group A';
  var labelB = groups.b || 'Group B';
  var hints = (d.regionHints && typeof d.regionHints === 'object') ? d.regionHints : {};
  var fb = (d.feedback && typeof d.feedback === 'object') ? d.feedback : {};
