      '.Interact_VennDiagram__subtitle{font-size:13px;line-height:1.5;color:#94a3b8;margin:0;}',
      '.Interact_VennDiagram__status{display:flex;align-items:center;flex-wrap:wrap;gap:8px;margin:0 0 12px;min-height:24px;}',
      '.Interact_VennDiagram__msg{font-size:13px;line-height:1.4;padding:6px 10px;border-radius:8px;border:1px solid #1f293d;',
      '  background:rgba(56,189,248,0.08);color:#94a3b8;transition:color 160ms ease,border-color 160ms ease,background 160ms ease;}',
      '.Interact_VennDiagram__msg--ok{color:#34d399;border-color:rgba(52,211,153,0.45);background:rgba(52,211,153,0.12);}',
      '.Interact_VennDiagram__msg--no{color:#f87171;border-color:rgba(248,113,113,0.45);background:rgba(248,113,113,0.12);}',
      '.Interact_VennDiagram__progress{font-size:12px;font-weight:600;color:#94a3b8;margin-left:auto;',
      '  padding:4px 10px;border:1px solid #1f293d;border-radius:999px;white-space:nowrap;}',
      '.Interact_VennDiagram__progress--done{color:#34d399;border-color:rgba(52,211,153,0.5);}',

      '.Interact_VennDiagram__diagram{position:relative;width:100%;aspect-ratio:16/10;min-height:190px;margin:0 0 12px;',
      '  border:1px solid #1f293d;border-radius:12px;background:#090d16;overflow:hidden;touch-action:manipulation;}',
      '.Interact_VennDiagram__diagram--hot{border-color:#38bdf8;box-shadow:0 0 0 2px rgba(56,189,248,0.15);}',
      '.Interact_VennDiagram__region{position:absolute;top:0;bottom:0;cursor:pointer;-webkit-tap-highlight-color:transparent;',
      '  transition:background 150ms ease,border-color 150ms ease;border:1px dashed transparent;border-radius:12px;}',
      '.Interact_VennDiagram__region--a{left:2%;width:56%;}',
      '.Interact_VennDiagram__region--b{right:2%;width:56%;}',
      '.Interact_VennDiagram__region--both{left:32%;width:36%;z-index:2;background:transparent;}',
      '.Interact_VennDiagram__region[data-active="1"]{border-color:#38bdf8;background:rgba(56,189,248,0.12);}',
      '.Interact_VennDiagram__region[data-flash="ok"]{background:rgba(52,211,153,0.16);border-color:rgba(52,211,153,0.6);}',
      '.Interact_VennDiagram__region[data-flash="no"]{background:rgba(248,113,113,0.16);border-color:rgba(248,113,113,0.6);}',
      '.Interact_VennDiagram__glabel{position:absolute;top:8px;font-size:11px;font-weight:700;letter-spacing:0.04em;',
      '  text-transform:uppercase;color:#94a3b8;pointer-events:none;max-width:34%;line-height:1.25;text-align:center;}',
      '.Interact_VennDiagram__glabel--a{left:8%;}',
      '.Interact_VennDiagram__glabel--b{right:8%;}',
      '.Interact_VennDiagram__ghint{display:block;font-weight:500;text-transform:none;letter-spacing:0;color:#64748b;margin-top:2px;font-size:10px;}',
      '.Interact_VennDiagram__svg{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;z-index:1;}',
      '.Interact_VennDiagram__stack{position:absolute;z-index:3;display:flex;flex-wrap:wrap;gap:4px;align-items:flex-start;',
      '  justify-content:center;align-content:flex-start;overflow:auto;padding:4px;max-height:calc(100% - 34px);}',
      '.Interact_VennDiagram__stack--a{left:6%;top:34px;width:34%;}',
      '.Interact_VennDiagram__stack--b{right:6%;top:34px;width:34%;}',
      '.Interact_VennDiagram__stack--both{left:33%;top:34px;width:34%;}',

      '.Interact_VennDiagram__chip{display:inline-flex;align-items:center;max-width:100%;min-height:32px;padding:5px 10px;',
      '  border-radius:8px;border:1px solid #334155;background:#111827;color:#f8fafc;',
      '  font:600 12px/1.25 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;text-align:center;',
      '  cursor:pointer;user-select:none;-webkit-user-select:none;-webkit-tap-highlight-color:transparent;',
      '  transition:transform 150ms ease,border-color 150ms ease,background 150ms ease,box-shadow 150ms ease;}',
      '.Interact_VennDiagram__chip:hover{border-color:#38bdf8;box-shadow:0 0 0 3px rgba(56,189,248,0.15);}',
      '.Interact_VennDiagram__chip[data-sel="1"]{border-color:#38bdf8;background:rgba(56,189,248,0.18);',
      '  box-shadow:0 0 0 3px rgba(56,189,248,0.22);transform:translateY(-1px);}',
      '.Interact_VennDiagram__chip--placed{cursor:pointer;}',
      '.Interact_VennDiagram__chip--ok{border-color:rgba(52,211,153,0.7);}',

      '.Interact_VennDiagram__pool{display:flex;flex-wrap:wrap;gap:8px;min-height:48px;padding:10px;border:1px dashed #334155;',
      '  border-radius:10px;background:rgba(56,189,248,0.03);transition:border-color 150ms ease,background 150ms ease;}',
      '.Interact_VennDiagram__pool--hot{border-color:#38bdf8;background:rgba(56,189,248,0.10);}',
      '.Interact_VennDiagram__pool--empty{border-style:solid;border-color:#1f293d;justify-content:center;align-items:center;}',
      '.Interact_VennDiagram__poolnote{font-size:12px;color:#94a3b8;margin:0 0 8px;line-height:1.4;}',

      '.Interact_VennDiagram__btns{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px;}',
      '.Interact_VennDiagram__btn{min-height:40px;padding:0 16px;border-radius:8px;border:1px solid #38bdf8;background:rgba(56,189,248,0.12);',
      '  color:#38bdf8;font:600 13px/1 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;cursor:pointer;',
      '  -webkit-tap-highlight-color:transparent;transition:background 150ms ease,transform 120ms ease,border-color 150ms ease;}',
      '.Interact_VennDiagram__btn:hover{background:rgba(56,189,248,0.22);}',
      '.Interact_VennDiagram__btn:active{transform:scale(0.97);}',
      '.Interact_VennDiagram__btn--ghost{border-color:#334155;background:transparent;color:#94a3b8;}',
      '.Interact_VennDiagram__btn--ghost:hover{background:rgba(56,189,248,0.10);color:#38bdf8;}',
      '.Interact_VennDiagram__btn:disabled{opacity:0.45;cursor:default;transform:none;}',

      '@media (max-width:420px){',
      '  .Interact_VennDiagram__card{padding:12px;}',
      '  .Interact_VennDiagram__title{font-size:16px;}',
      '  .Interact_VennDiagram__chip{font-size:11px;padding:5px 8px;}',
      '  .Interact_VennDiagram__glabel{font-size:10px;}',
      '  .Interact_VennDiagram__stack--a{left:4%;width:36%;} .Interact_VennDiagram__stack--b{right:4%;width:36%;} .Interact_VennDiagram__stack--both{left:32%;width:36%;}',
      '}',
      '@media (prefers-reduced-motion: reduce){',
      '  .Interact_VennDiagram__card *,.Interact_VennDiagram__card *::before,.Interact_VennDiagram__card *::after{',
      '    transition-duration:1ms !important;animation-duration:1ms !important;}',
