    hintLbl.className = 'game_hangmangallows__hintlabel';
    hintLbl.textContent = lblHint;
    var hintTxt = document.createElement('span');
    hintTxt.textContent = hint;
    hintBox.appendChild(hintLbl);
    hintBox.appendChild(hintTxt);
