  var bulbLabel = (data && data.bulbLabel) || 'BULB';
  var branchPrefix = (data && data.branchLabelPrefix) || '';
  var successMessage = (data && data.successMessage) || 'Circuit complete — the bulb is lit.';

  var rawBranches = (data && Array.isArray(data.branches)) ? data.branches : [];
  var branches = [];
