  var bulbWrap = document.createElement('div');
  bulbWrap.className = TAG + '__bulb';
  bulbWrap.innerHTML =
    '<svg width="72" height="80" viewBox="0 0 72 80" aria-hidden="true">' +
      '<defs><radialGradient id="' + TAG + '_g"><stop offset="0%" stop-color="#fbbf24" stop-opacity="0.9"/><stop offset="100%" stop-color="#fbbf24" stop-opacity="0"/></radialGradient></defs>' +
      '<circle class="bulbGlow" cx="36" cy="32" r="30" fill="url(#' + TAG + '_g)"/>' +
      '<g class="bulbg" data-bulb>' +
        '<circle class="bulbGlass" cx="36" cy="32" r="20" fill="#090d16" stroke="#334155" stroke-width="2"/>' +
        '<path class="bulbFil" d="M28 46 L31 34 L36 40 L41 34 L44 46" fill="none" stroke="#334155" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>' +
        '<rect x="28" y="50" width="16" height="6" rx="2" fill="#334155"/>' +
        '<rect x="29" y="58" width="14" height="5" rx="2" fill="#334155"/>' +
        '<g class="bulbRays" stroke="#fbbf24" stroke-width="2" stroke-linecap="round">' +
          '<line x1="36" y1="4" x2="36" y2="10"/><line x1="14" y1="14" x2="18" y2="18"/><line x1="58" y1="14" x2="54" y2="18"/><line x1="8" y1="32" x2="14" y2="32"/><line x1="64" y1="32" x2="58" y2="32"/>' +
        '</g>' +
      '</g>' +
    '</svg>';
  var blb = document.createElement('div');
  blb.className = TAG + '__bulblabel';
  blb.textContent = bulbLabel;
  bulbWrap.appendChild(blb);
  board.appendChild(bulbWrap);

  wrap.appendChild(board);

  // palette
  var pal = document.createElement('div');
  pal.className = TAG + '__palette';
  var pt = document.createElement('p');
  pt.className = TAG + '__paletitle';
