        ic.innerHTML = iconFor(comp.kind);
        el.appendChild(ic);
        var lb = document.createElement('div');
        lb.className = TAG + '__chiplabel';
        lb.textContent = comp.label;
        el.appendChild(lb);
        if (comp.detail) {
          var dd = document.createElement('div');
          dd.className = TAG + '__chipdetail';
          dd.textContent = comp.detail;
          el.appendChild(dd);
        }
        if (selectedComponentId === comp.id) el.classList.add(TAG + '__pcard--sel');
        var usedElsewhere = isUsed(comp.id);
