  var catSelect = el('select', TAG + '__select');
  catSelect.setAttribute('aria-label', 'Conversion family');
  catField.appendChild(catSelect);
  panel.appendChild(catField);

  // amount
  var amtField = el('div', TAG + '__field');
  amtField.appendChild(el('label', TAG + '__label', 'Amount'));
  var amtInput = el('input', TAG + '__input');
  amtInput.type = 'text';
  amtInput.inputMode = 'decimal';
  amtInput.autocomplete = 'off';
  amtInput.setAttribute('aria-label', 'Amount to convert');
  amtField.appendChild(amtInput);
  panel.appendChild(amtField);

  // from / swap / to
  var grid = el('div', TAG + '__grid');
  var fromField = el('div', TAG + '__field');
  fromField.appendChild(el('label', TAG + '__label', 'From'));
  var fromSelect = el('select', TAG + '__select');
  fromSelect.setAttribute('aria-label', 'Convert from unit');
  fromField.appendChild(fromSelect);
  var swapBtn = el('button', TAG + '__swap', '⇄');
  swapBtn.type = 'button';
  swapBtn.setAttribute('aria-label', 'Swap units');
  var toField = el('div', TAG + '__field');
  toField.appendChild(el('label', TAG + '__label', 'To'));
  var toSelect = el('select', TAG + '__select');
  toSelect.setAttribute('aria-label', 'Convert to unit');
