  syncCatSelect();
  // pick default unit indices if provided
  var initUnits = cats[state.cat].units;
  if (defaults.fromUnitId) initUnits.forEach(function (u, i) { if (u && u.id === defaults.fromUnitId) state.from = i; });
  if (defaults.toUnitId) initUnits.forEach(function (u, i) { if (u && u.id === defaults.toUnitId) state.to = i; });
  if (state.to === state.from) state.to = (state.from === 0) ? 1 : 0;
