  function drawBadgeCanvas(cb) {
    var W = 800, H = 1000;
    var canvas = document.createElement("canvas");
    canvas.width = W;
    canvas.height = H;
    var ctx = canvas.getContext("2d");
    var pad = 60;

    ctx.fillStyle = "#090d16";
    ctx.fillRect(0, 0, W, H);

    roundRect(ctx, pad / 2, pad / 2, W - pad, H - pad, 24);
    ctx.fillStyle = "#111827";
    ctx.fill();
    ctx.lineWidth = 2;
    ctx.strokeStyle = "#1f293d";
    ctx.stroke();

    var x = pad + 20;
    var y = pad + 40;

    if (T.subject) {
      ctx.font = "600 22px -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif";
      ctx.fillStyle = "#94a3b8";
      ctx.textBaseline = "top";
      y = drawWrapped(ctx, T.subject.toUpperCase(), x, y, W - 2 * x, 28) + 10;
    }

    ctx.font = "700 44px -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif";
    ctx.fillStyle = "#f8fafc";
    y = drawWrapped(ctx, T.title, x, y, W - 2 * x, 54) + 8;

    if (T.student) {
      ctx.font = "400 28px -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif";
      ctx.fillStyle = "#94a3b8";
      ctx.fillText(T.student, x, y);
      y += 46;
    }

    y += 24;

    var cx = W / 2;
    var cy = y + 170;
    var radius = 140;

    ctx.beginPath();
    ctx.arc(cx, cy, radius, 0, 2 * Math.PI);
    ctx.lineWidth = 32;
    ctx.strokeStyle = "#1f293d";
    ctx.stroke();

    ctx.beginPath();
    var start = -Math.PI / 2;
    ctx.arc(cx, cy, radius, start, start + 2 * Math.PI * (T.score / 100));
    ctx.lineWidth = 32;
    ctx.lineCap = "round";
    ctx.strokeStyle = tierColor;
    ctx.stroke();

    ctx.textAlign = "center";
    ctx.textBaseline = "alphabetic";
    ctx.fillStyle = "#f8fafc";
    ctx.font = "800 84px -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif";
    ctx.fillText(Math.round(T.score) + "%", cx, cy + 16);
    ctx.fillStyle = "#94a3b8";
    ctx.font = "600 22px -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif";
    ctx.fillText("SCORE", cx, cy + 56);

    y = cy + radius + 50;

    ctx.textAlign = "left";
    ctx.textBaseline = "top";
    ctx.fillStyle = "#94a3b8";
    ctx.font = "600 22px -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif";
    ctx.fillText("MASTERY LEVEL", x, y);
    y += 32;

    ctx.fillStyle = tierColor;
    ctx.font = "700 52px -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif";
    ctx.fillText(T.mastery, x, y);
    y += 76;

    if (T.statValue || T.statLabel) {
      ctx.fillStyle = "#38bdf8";
      ctx.font = "700 36px -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif";
      var statStr = (T.statValue || "") + (T.statLabel ? "  " + T.statLabel : "");
      ctx.fillText(statStr, x, y);
      y += 66;
    }

    if (T.tagline) {
      y += 10;
      var boxH = measureWrapped(ctx, T.tagline, "400 28px -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif", W - 2 * x - 40, 40) + 32;
      roundRect(ctx, x, y, W - 2 * x, boxH, 16);
      ctx.fillStyle = "rgba(56,189,248,0.15)";
      ctx.fill();
      ctx.fillStyle = "#38bdf8";
      ctx.fillRect(x, y, 8, boxH);
      ctx.fillStyle = "#f8fafc";
      ctx.font = "400 28px -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif";
      drawWrapped(ctx, T.tagline, x + 28, y + 16, W - 2 * x - 56, 40);
      y += boxH + 16;
    }

    var footY = H - pad - 40;
    ctx.strokeStyle = "#1f293d";
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(x, footY - 22);
    ctx.lineTo(W - x, footY - 22);
    ctx.stroke();

    ctx.font = "400 22px -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif";
    ctx.fillStyle = "#94a3b8";
    ctx.textBaseline = "top";
    if (T.dateLabel) ctx.fillText(T.dateLabel, x, footY);
    if (T.credentialId) {
      ctx.textAlign = "right";
      ctx.font = "400 22px ui-monospace, SFMono-Regular, Menlo, monospace";
      ctx.fillText(T.credentialId, W - x, footY);
      ctx.textAlign = "left";
    }

    cb(canvas);

    function roundRect(c, rx, ry, rw, rh, rad) {
      c.beginPath();
      c.moveTo(rx + rad, ry);
      c.lineTo(rx + rw - rad, ry);
      c.quadraticCurveTo(rx + rw, ry, rx + rw, ry + rad);
      c.lineTo(rx + rw, ry + rh - rad);
      c.quadraticCurveTo(rx + rw, ry + rh, rx + rw - rad, ry + rh);
      c.lineTo(rx + rad, ry + rh);
      c.quadraticCurveTo(rx, ry + rh, rx, ry + rh - rad);
      c.lineTo(rx, ry + rad);
      c.quadraticCurveTo(rx, ry, rx + rad, ry);
      c.closePath();
    }

    function wrapLines(c, text, font, maxW) {
      c.font = font;
      var words = String(text).split(/\s+/);
      var lines = [];
      var line = "";
      for (var i = 0; i < words.length; i++) {
        var test = line ? line + " " + words[i] : words[i];
        if (c.measureText(test).width > maxW && line) {
          lines.push(line);
          line = words[i];
        } else {
          line = test;
        }
      }
      if (line) lines.push(line);
      return lines;
    }

    function drawWrapped(c, text, dx, dy, maxW, lh) {
      var font = c.font;
      var lines = wrapLines(c, text, font, maxW);
      for (var i = 0; i < lines.length; i++) {
        c.fillText(lines[i], dx, dy + i * lh);
      }
      return dy + (lines.length - 1) * lh;
    }

    function measureWrapped(c, text, font, maxW, lh) {
      return wrapLines(c, text, font, maxW).length * lh;
    }
  }

